const agora = new Date().toISOString();

return [{
  json: {
    schema_version: "1.0",
    request_id: `SOC-${Date.now()}`,
    execution_id: String($execution.id ?? "manual"),
    created_at: agora,
    environment: "LAB",
    trigger: {
      type: "manual_test",
      interval_minutes: 5
    },
    action: "collect_events",
    target_workflow: "WF-01",
    source: "SOC-LAB",
    window: {
      minutes: 5,
      end: agora
    },
    test_event: {
      event_id: "LAB-0001",
      source: "SOC-LAB",
      timestamp: agora,
      event_type: "suspicious_connection",
      severity: "medium",
      src_ip: "192.0.2.10",
      dst_ip: "198.51.100.20",
      hostname: "lab-workstation-01",
      description: "Evento sintetico para teste."
    }
  }
}];

const request = $input.first().json;
const erros = [];

const obrigatorios = [
  "schema_version",
  "request_id",
  "environment",
  "trigger",
  "action",
  "target_workflow",
  "source",
  "window"
];

for (const campo of obrigatorios) {
  if (
    request[campo] === undefined ||
    request[campo] === null ||
    request[campo] === ""
  ) {
    erros.push(`Campo obrigatorio ausente: ${campo}`);
  }
}

if (request.environment !== "LAB") {
  erros.push("Somente ambiente LAB permitido.");
}

if (request.action !== "collect_events") {
  erros.push("Acao nao permitida.");
}

if (request.target_workflow !== "WF-01") {
  erros.push("Destino invalido.");
}

if (
  !request.window ||
  !Number.isInteger(request.window.minutes) ||
  request.window.minutes <= 0
) {
  erros.push("Janela de coleta invalida.");
}

if (erros.length > 0) {
  throw new Error(erros.join(" | "));
}

return [{
  json: {
    ...request,
    validation: {
      status: "VALID",
      checked_at: new Date().toISOString(),
      errors: []
    }
  }
}];

const request = $input.first().json;

if (request.validation?.status !== "VALID") {
  throw new Error("Despacho bloqueado.");
}

return [{
  json: {
    request_id: request.request_id,
    schema_version: request.schema_version,
    environment: request.environment,
    orchestrator: "WF-00",
    requested_action: request.action,
    destination: request.target_workflow,
    dispatch_status: "MOCK_ONLY",
    real_execution_started: false,
    received_at: request.created_at,
    processed_at: new Date().toISOString(),
    collection_window_minutes: request.window.minutes,
    test_event: request.test_event,
    message: "Contrato validado. Despacho simulado."
  }
}];
